using Microsoft.Extensions.DependencyInjection;
using Runic.Application.Views.Desktop;

namespace Acme.App;

public static class AppServices
{
    // Program.cs opens the Window with these services; the tests build the same graph.
    public static IServiceCollection AddAcmeApp(this IServiceCollection services)
    {
        services.AddScoped<CounterViewModel>();
        // Generated by the build: the Window's Bridge and the View locator.
        services.AddRunicViews();
        services.AddRunicPlatformServices();
        return services;
    }
}
